{"name": "sum_squared_digits", "code": "def solve(inputs: dict) -> float:
    N = inputs['N']
    K = inputs['K']

    def sum_of_squared_digits(n):
        total = 0
        while n > 0:
            digit = n % 10
            total += digit * digit
            n //= 10
        return total

    current = N
    for _ in range(K):
        current = sum_of_squared_digits(current)

    return float(current)
"}
